function dramaCard(d,compact){compact=collapsedCards.has(d.id)||(compact&&!expandedCards.has(d.id));const names=[...new Set(d.members.map(m=>SOURCE_NAMES[m.source]))],isDisliked=d.members.some(m=>disliked.includes(m.id));return `<article class="card${compact?' compact-card':''}${isDisliked?' disliked-card':''}">${isDisliked?dislikeStamp(d.id):''}<div class="top" data-expand-card="${d.id}">${`<div class="cover"><span class="cover-placeholder">暂无封面</span><img loading="lazy" data-cover="${d.id}" alt="${esc(d.title)}封面" referrerpolicy="no-referrer" decoding="async" hidden></div>`}<div class="drama-info"><h2>${esc(d.title)}</h2>${compact?'':`<div class="en">${esc(d.en)}</div>${aliasPreview(d)}`}${scorePreview(d)}<div class="drama-controls">${watchButtons(d)}${`<button class="card-toggle" data-card-toggle="${d.id}" aria-expanded="${!compact}">${compact?'展开详情':'收起详情'}</button>`}</div>${compact?'':`<div class="card-actions"><button data-id="${d.id}" aria-pressed="${d.members.some(m=>saved.includes(m.id))}">${d.members.some(m=>saved.includes(m.id))?'已收藏':'收藏这部剧'}</button><button data-dislike="${d.id}" aria-pressed="${d.members.some(m=>disliked.includes(m.id))}">${d.members.some(m=>disliked.includes(m.id))?'已狠踩':'狠踩'}</button><button data-suggest="${d.id}">别名 / 合并 / 拆分</button></div>${proposalsFor(d)}`}</div></div>${compact?'':`<details class="source-details" open><summary>来源：${esc(names.join(' · '))}</summary><div class="rows">${sourceRows(d)}</div></details>`}</article>`;}
function toggleDrama(id){const compact=collapsedCards.has(id)||($('#display-mode').value==='compact'&&!expandedCards.has(id));if(compact){collapsedCards.delete(id);expandedCards.add(id);}else{expandedCards.delete(id);collapsedCards.add(id);}render();}
const browseFields=['q','source-filter','date-filter','date-end','min-rating','tag-filter','sort-filter'];
function saveBrowseState(){try{sessionStorage.setItem('drama-browse-state',JSON.stringify({values:Object.fromEntries(browseFields.map(id=>[id,$('#'+id).value])),tags:selectedTags,onlyFav,watchFilter,hideWatched:$('#hide-watched').checked}));}catch{}}
function restoreBrowseState(){try{const state=JSON.parse(sessionStorage.getItem('drama-browse-state')||'null');if(!state||typeof state!=='object')return;for(const id of browseFields){const value=state.values?.[id];if(typeof value!=='string'||value.length>500)continue;if(id==='source-filter'&&!['','a','b','c','d'].includes(value))continue;if(id==='sort-filter'&&!['latest','rating'].includes(value))continue;if(id==='date-filter'&&value&&!/^\d{4}-\d{2}-\d{2}$/.test(value))continue;if(id==='date-end'&&!['','same'].includes(value)&&!/^\d{4}-\d{2}-\d{2}$/.test(value))continue;if(id==='date-end'&&/^\d{4}-\d{2}-\d{2}$/.test(value))$('#date-end').innerHTML+='<option value="'+value+'">'+value+'</option>';$('#'+id).value=value;}selectedTags.splice(0,selectedTags.length,...(Array.isArray(state.tags)?state.tags.filter(t=>t&&typeof t.tag==='string'&&t.tag.length<=80&&['','a','b','c','d'].includes(t.source)).slice(0,100):[]));onlyFav=state.onlyFav===true;watchFilter=['watched','want'].includes(state.watchFilter)?state.watchFilter:'';$('#hide-watched').checked=state.hideWatched===true;}catch{}}
function render(){
 saveBrowseState();
 $('#open-date-calendar').textContent=$('#date-filter').value||'选择日期 ▦';
 const q=norm($('#q').value);const groups=groupedCatalog();let items=groups.filter(d=>(!onlyFav||d.members.some(m=>saved.includes(m.id)))&&(!watchFilter||groupWatchStatus(d)===watchFilter)&&(!$('#hide-watched').checked||groupWatchStatus(d)!=='watched')&&matchesCatalogFilters(d)&&nameMatches([d.title,d.en,...d.aliases],q));
 const sort=$('#sort-filter').value;items.sort((a,b)=>(sort==='rating'?Math.max(0,...b.members.map(m=>m.score?.[0]||0))-Math.max(0,...a.members.map(m=>m.score?.[0]||0)):0)||compareLatest(a,b));
 const total=items.length,pages=Math.max(1,Math.ceil(total/PAGE_SIZE));page=Math.min(page,pages);$('#catalog-summary').textContent=`${total} 部剧集 · ${catalogMeta?.sourceRecordCount||0} 条来源记录 · 第 ${page}/${pages} 页`;$('#page-label').textContent=`${page} / ${pages}`;$('#previous-page').disabled=page<=1;$('#next-page').disabled=page>=pages;items=items.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE);
 $('#result').innerHTML=items.length?items.map(d=>dramaCard(d,$('#display-mode').value==='compact')).join(''):'<div id="empty">没有匹配的剧集。</div>';
 document.querySelectorAll('[data-cover]').forEach(img=>setupCover(img,groups.find(d=>d.id===img.dataset.cover)));paintCounts();
 document.querySelectorAll('[data-watch]').forEach(b=>b.onclick=()=>toggleWatchStatus(groups.find(d=>d.id===b.dataset.watchGroup),b.dataset.watch,b));
 document.querySelectorAll('[data-dislike]').forEach(b=>b.onclick=()=>toggleDislike(groups.find(d=>d.id===b.dataset.dislike),b));
 document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>toggleFavorite(groups.find(d=>d.id===b.dataset.id),b));
 document.querySelectorAll('[data-alias-toggle]').forEach(b=>b.onclick=()=>{const expanded=b.getAttribute('aria-expanded')!=='true';b.parentElement.classList.toggle('is-expanded',expanded);b.setAttribute('aria-expanded',String(expanded));b.textContent=expanded?'收起':'展开';});
 document.querySelectorAll('[data-card-toggle]').forEach(b=>b.onclick=()=>toggleDrama(b.dataset.cardToggle));
 document.querySelectorAll('[data-expand-card]').forEach(top=>top.onclick=e=>{if(e.target.closest('button,a,input,select,textarea'))return;toggleDrama(top.dataset.expandCard);});
 document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>openProposal(b.dataset.suggest));bindProposalVotes();
}
const titleFor=id=>data.find(d=>d.id===id)?.title||'未知剧集';
function proposalTitleFor(id){const record=data.find(d=>d.id===id);return record?record.title+' · '+SOURCE_NAMES[record.source]:(catalogLoaded?'该记录已不在当前目录':'剧名加载中…');}
function proposalRow(p){const split=p.kind==='split',pair=p.kind!=='alias';return `<article class="proposal"><div><span class="proposal-kind">${split?'拆分':pair?'合并':'别名'}</span> <strong>${esc(proposalTitleFor(p.left_id))}</strong><span class="proposal-pair">${split?'不是同一部':pair?'与':'也叫'}</span><strong>${esc(pair?proposalTitleFor(p.right_id):p.alias_name)}</strong></div>${p.reason?`<p class="proposal-reason">依据：${esc(p.reason)}</p>`:''}<div class="proposal-bottom"><span class="proposal-status ${p.approved?'approved':''}">${p.approved?(split?'已通过拆分':pair?'已通过':'已添加别名'):`${p.votes} / ${threshold} 个支持`}</span>${p.approved?`<span class="count">${p.votes} 个支持</span>`:`<button data-vote="${p.id}" ${p.supported?'disabled':''}>${p.supported?'本浏览器已支持':split?'确认不是同一部':'我也确认是同一部'}</button>`}</div></article>`;}
function proposalsFor(d){const ids=new Set(d.members.map(m=>m.id));const related=proposals.filter(p=>!p.approved&&(ids.has(p.left_id)||(p.kind!=='alias'&&ids.has(p.right_id))));return related.length?`<section class="drama-proposals" aria-label="本剧别名、合并与拆分提议"><h3>本剧的别名 / 合并 / 拆分提议</h3>${related.map(proposalRow).join('')}</section>`:'';}
function bindProposalVotes(){document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await postAlias('/api/aliases/vote',{id:b.dataset.vote});$('#community-status').textContent='支持已记录。达到 2 个浏览器支持后自动生效。';}catch(error){$('#community-status').textContent=error.message;b.disabled=false;}});}
function renderProposals(){
 const pending=proposals.filter(p=>!p.approved),approved=proposals.filter(p=>p.approved);$('#proposal-list').innerHTML=aliasLoaded?`<details class="community-proposals"><summary>待确认的提议（${pending.length}）</summary>${pending.length?pending.map(proposalRow).join(''):'<p class="count">暂无待确认的提议</p>'}</details><details class="community-proposals"><summary>已通过的提议（${approved.length}）</summary>${approved.length?approved.map(proposalRow).join(''):'<p class="count">暂无已通过的提议</p>'}</details>`:'正在加载社区提议…';
 bindProposalVotes();
}
async function loadAliases(){try{const r=await fetch('/api/aliases',{cache:'no-store'});if(!r.ok)throw Error();const result=await r.json();proposals=result.proposals;threshold=result.threshold;aliasLoaded=true;$('#community-status').textContent='';render();renderProposals();}catch{$('#community-status').textContent='社区提议暂时无法加载。已有样本仍可使用，请稍后点击刷新。';}}
async function postAlias(path,body){const r=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(result.error||'操作失败，请重试');proposals=result.proposals;threshold=result.threshold;aliasLoaded=true;render();renderProposals();}
function updateProposalMode(){const pair=$('#proposal-kind').value!=='alias',split=$('#proposal-kind').value==='split';$('#alias-name-wrap').hidden=pair;$('#merge-target-wrap').hidden=!pair;$('#alias-name').required=!pair;$('#merge-target').required=pair;$('#merge-target-label').textContent=split?'选择要分开的另一条来源记录':'选择另一部剧';$('#merge-target-hint').textContent=split?'选择当前卡片中被误认成同一部剧的记录。通过后两条记录分开展示，并保留各自评分与链接。':'请核实英文名、角色或剧情，确认是同一部再合并。';updateMergeTargets();}
