$('#firebase-action-form').onsubmit=async event=>{event.preventDefault();if(!firebaseActionState)return;const button=$('#firebase-action-submit');button.disabled=true;try{const result=await accountRequest('/api/account/firebase/action',{...firebaseActionState,...(firebaseActionState.mode==='resetPassword'?{password:$('#firebase-new-password').value}:{})});if(firebaseActionState.mode==='resetPassword'){++accountEpoch;account=null;saved=localSaved.slice();disliked=localDisliked.slice();watchState={...localWatchState};paintAccount();render();}$('#firebase-action-message').textContent=result.message;$('#firebase-action-form').hidden=true;$('#firebase-new-password').value='';firebaseActionState=null;$('#firebase-action-close').textContent='返回登录';if(typeof history!=='undefined')history.replaceState(null,'','/');}catch(error){$('#firebase-action-message').textContent=error.message;}finally{button.disabled=false;}};
$('#firebase-action-close').onclick=()=>{firebaseActionState=null;$('#firebase-new-password').value='';closeAccountDialog('#firebase-action-dialog');if(typeof history!=='undefined')history.replaceState(null,'','/');$('#account-mode').value='login';showAccountDialog();};
if(typeof location!=='undefined'){const action=new URLSearchParams(location.search),mode=action.get('mode'),oobCode=action.get('oobCode');if(['verifyEmail','resetPassword'].includes(mode)&&oobCode){firebaseActionState={mode,oobCode};$('#firebase-action-title').textContent=mode==='verifyEmail'?'验证邮箱':'重设密码';$('#firebase-action-message').textContent=mode==='verifyEmail'?'请点击下方按钮完成邮箱验证，之后返回原页面登录或完成绑定。':'请输入至少 8 位的新密码。';$('#firebase-reset-wrap').hidden=mode!=='resetPassword';$('#firebase-new-password').required=mode==='resetPassword';$('#firebase-action-submit').textContent=mode==='verifyEmail'?'验证邮箱':'保存新密码';const dialog=$('#firebase-action-dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}}
